class Solution{public boolean isOneEditDistance(String s,String t){if(s.length()>t.length())return isOneEditDistance(t,s);if(t.length()-s.length()>1)return false;int i=0;while(i<s.length()&&s.charAt(i)==t.charAt(i))i++;if(i==s.length())return t.length()==s.length()+1;if(s.length()==t.length())i++;while(i<s.length()&&s.charAt(i)==t.charAt(i+t.length()-s.length()))i++;return i==s.length();}}
